-- 제철식품관(G_SEASON_FOOD) AS-IS 실데이터 적재 (2026-10-19)
--
-- 기존 12행은 TO-BE 시드가 지어낸 월별 문구 한 줄("겨울 보양 제철 답례품" 등)이었다. AS-IS는 키워드마다 한 행(월 + 등록순번)이라
-- AS-IS 개발DB(10.0.120.51:30000/ghlove2) G_SEASON_FOOD 284행(1~12월, 월당 14~35개)으로 교체한다.
-- G_SEASON_FOOD_ITEM(월별 제철 상품 매핑)은 건드리지 않는다.
--
-- 적용: MSYS_NO_PATHCONV=1 docker run --rm -i -e PGPASSWORD=<gift 비밀번호> postgres:16-alpine \
--         psql -h <DB 호스트> -p 15432 -U gift -d gift < migration-gift-season-food-asis-data.sql

BEGIN;

DELETE FROM g_season_food;


COMMIT;

SELECT season_food_month, count(*) FROM g_season_food GROUP BY 1 ORDER BY 1;
